import unittest
from unittest.mock import Mock, call, patch

import config
import importers


class UniClubsDownloadTests(unittest.TestCase):
    """Exercise HTTP errors, content limits and UTF-8 decoding with mocked responses."""

    def setUp(self):
        """Replace only HTTP transport, preserving the real download function."""
        replacement = patch('importers.requests.get')
        self.get = replacement.start()
        self.addCleanup(replacement.stop)
        self.response = self.get.return_value.__enter__.return_value
        self.response.status_code = 200
        self.response.headers = {'Content-Type': 'text/html; charset=utf-8'}
        self.response.iter_content.return_value = ['<html>Zürich</html>'.encode('utf-8')]

    def test_download_is_bounded_public_https_without_authentication(self):
        """Decode the public page while retaining TLS verification and a timeout."""
        self.response.headers = {'Content-Type': 'Text/HTML; charset=utf-8'}
        self.assertEqual(importers.fetch_uniclubs_events_html(), '<html>Zürich</html>')
        args, options = self.get.call_args
        self.assertEqual(args, (config.UNICLUBS_EVENTS_URL,))
        self.assertEqual(options['timeout'], config.HTTP_TIMEOUT_SECONDS)
        self.assertTrue(options['stream'])
        self.assertFalse(options['allow_redirects'])
        self.assertIsNot(options.get('verify'), False)
        self.assertNotIn('auth', options)
        self.assertNotIn('cookies', options)
        self.assertNotIn('Authorization', options['headers'])
        self.get.return_value.__exit__.assert_called_once()

    def test_http_failure_does_not_expose_transport_details(self):
        """Keep diagnostic query strings out of user-facing download errors."""
        self.response.raise_for_status.side_effect = importers.requests.HTTPError('secret=hidden')
        with self.assertRaises(ValueError) as result:
            importers.fetch_uniclubs_events_html()
        self.assertNotIn('secret', str(result.exception))
        self.get.return_value.__exit__.assert_called_once()

    def test_timeout_is_reported_without_raw_network_details(self):
        """A connection timeout must become a controlled error rather than a partial page."""
        self.get.side_effect = importers.requests.Timeout('private transport details')
        with self.assertRaises(ValueError) as result:
            importers.fetch_uniclubs_events_html()
        self.assertNotIn('private', str(result.exception))

    def test_non_html_content_is_rejected(self):
        """A JSON response or error document must not masquerade as the observed HTML route."""
        self.response.headers = {'Content-Type': 'application/json'}
        with self.assertRaises(ValueError):
            importers.fetch_uniclubs_events_html()
        self.response.iter_content.assert_not_called()

    def test_redirect_is_rejected_without_following_another_route(self):
        """A moved page must be inspected before requesting an unknown destination."""
        self.response.status_code = 302
        with self.assertRaises(ValueError):
            importers.fetch_uniclubs_events_html()
        self.response.iter_content.assert_not_called()
        self.assertFalse(self.get.call_args.kwargs['allow_redirects'])

    def test_oversized_stream_aborts_and_closes_the_response(self):
        """Stop reading once decompressed response bytes exceed the configured limit."""
        self.response.iter_content.return_value = [b'12345678', b'abcdefgh']
        with patch.object(config, 'UNICLUBS_MAX_HTML_BYTES', 10):
            with self.assertRaises(ValueError):
                importers.fetch_uniclubs_events_html()
        self.get.return_value.__exit__.assert_called_once()

    def test_invalid_utf8_is_rejected(self):
        """Reject damaged source bytes rather than silently changing public event titles."""
        self.response.iter_content.return_value = [b'\xff']
        with self.assertRaises(ValueError):
            importers.fetch_uniclubs_events_html()

    def test_sitemap_download_accepts_public_xml(self):
        """Fetch only the configured public sitemap using the bounded verified transport."""
        self.response.headers = {'Content-Type': 'application/xml; charset=utf-8'}
        self.response.iter_content.return_value = [b'<urlset/>']
        self.assertEqual(importers.fetch_uniclubs_sitemap_xml(), '<urlset/>')
        self.assertEqual(self.get.call_args.args, (config.UNICLUBS_SITEMAP_URL,))
        self.assertFalse(self.get.call_args.kwargs['allow_redirects'])

    def test_sitemap_download_applies_its_own_byte_limit(self):
        """A large sitemap must not bypass the response size guard."""
        self.response.headers = {'Content-Type': 'text/xml'}
        self.response.iter_content.return_value = [b'<urlset/>']
        with patch.object(config, 'UNICLUBS_MAX_SITEMAP_BYTES', 2):
            with self.assertRaises(ValueError):
                importers.fetch_uniclubs_sitemap_xml()
        self.get.return_value.__exit__.assert_called_once()

    def test_sync_downloads_are_sequential_with_a_crawl_delay(self):
        """Wait between the two document requests without creating recurring work."""
        with patch('importers.fetch_uniclubs_events_html', return_value='html') as html:
            with patch('importers.fetch_uniclubs_sitemap_xml', return_value='xml') as sitemap:
                with patch('importers.sleep') as pause:
                    ordered = Mock()
                    ordered.attach_mock(html, 'html')
                    ordered.attach_mock(pause, 'pause')
                    ordered.attach_mock(sitemap, 'sitemap')
                    self.assertEqual(importers.fetch_uniclubs_sync_documents(), ('html', 'xml'))
        self.assertEqual(ordered.mock_calls,
                         [call.html(), call.pause(config.UNICLUBS_REQUEST_PAUSE_SECONDS),
                          call.sitemap()])

    def test_failed_overview_does_not_trigger_another_download(self):
        """A failed first request must stop the synchronization transport immediately."""
        with patch('importers.fetch_uniclubs_events_html', side_effect=ValueError('Unavailable')):
            with patch('importers.fetch_uniclubs_sitemap_xml') as sitemap:
                with patch('importers.sleep') as pause:
                    with self.assertRaises(ValueError):
                        importers.fetch_uniclubs_sync_documents()
        sitemap.assert_not_called()
        pause.assert_not_called()


if __name__ == '__main__':
    unittest.main()
